// ============================================================
// PARSEAR RESPUESTA DE GEMINI EN MENSAJES SEPARADOS
// ============================================================

// Extraer texto de la respuesta de Gemini
const geminiResponse = $input.first().json;
const responseText = geminiResponse.candidates?.[0]?.content?.parts?.[0]?.text || '';

if (!responseText) {
  throw new Error('Gemini no devolvió texto. Revisar la respuesta: ' + JSON.stringify(geminiResponse));
}

// Parsear mensajes separados por ---
const rawParts = responseText
  .split(/^\s*---\s*$/m)
  .map(p => p.trim())
  .filter(p => p.length > 0)
  .slice(0, 4); // máximo 4 mensajes

// Si Gemini no usó separadores, dividir en oraciones (fallback)
const parts = rawParts.length >= 2
  ? rawParts
  : responseText.split(/(?<=[.!?])\s+/).slice(0, 3);

// Recuperar datos del contexto (necesarios para el loop y la actualización de Notion)
const contextData = $('Construir Prompt con Contexto').first().json;
const subscriberId = contextData.subscriberId;
const notionPageId = contextData.notionPageId;

// Construir historial completo incluyendo la respuesta de la IA
const aiResponseForHistory = parts.join('\n');
const historialCompleto = contextData.historialConNuevoMsg + '\n[LA AGENCIA AI]: ' + aiResponseForHistory;

// Truncar si necesario (límite Notion rich_text API: 2000 chars)
const historialFinalParaNotion = historialCompleto.length > 1900
  ? '...' + historialCompleto.slice(-1900)
  : historialCompleto;

// Retornar cada mensaje como un item separado para el loop
return parts.map((message, index) => ({
  json: {
    message,
    // Delay en segundos: simula tipeo humano (2s base + 0.04s por char + random 0-3s)
    delaySeconds: Math.min(12, Math.max(2, Math.floor(2 + message.length * 0.04 + Math.random() * 3))),
    subscriberId,
    notionPageId,
    isLastMessage: index === parts.length - 1,
    historialFinalParaNotion,  // solo necesario en el último mensaje
    totalMessages: parts.length,
    messageIndex: index + 1
  }
}));
